mutation CreateAgentOrgDefinition($input: CreateAgentOrgDefinitionInput!) {
  createAgentOrgDefinition(input: $input) {
    ...AgentOrgDefinitionFields
    __typename
  }
}

fragment AgentOrgDefinitionFields on AgentOrgDefinition {
  id
  name
  description
  instructions
  category
  avatarUrl
  revision
  handoffs {
    from
    to
    rules
    __typename
  }
  members {
    memberName
    ref
    refType
    refScope
    __typename
  }
  defaultLaunchConfig {
    llmModelIdentifier
    runtimeKind
    llmConfig
    __typename
  }
  loadIssues {
    kind
    definitionId
    name
    code
    reason
    definitionPath
    packageRoot
    usingLastGood
    __typename
  }
  __typename
}

